// Build Miniflux Basic auth header
const authHeader = 'Basic ' + Buffer.from(`${$env.MINIFLUX_ADMIN_USER}:${$env.MINIFLUX_ADMIN_PASSWORD}`).toString('base64');
return [{ json: { authHeader } }];

const data = $input.first().json;
const since = new Date(Date.now() - 24 * 60 * 60 * 1000);

const entries = (data.entries || []).filter(e => new Date(e.published_at) >= since);

if (entries.length === 0) {
  return [{ json: { hasEntries: false, count: 0, prompt: '' } }];
}

const articleList = entries.slice(0, 60).map(e => ({
  id: e.id,
  title: e.title,
  feed: e.feed ? e.feed.title : 'Unknown',
  summary: (e.content || e.summary || '').replace(/<[^>]*>/g, '').substring(0, 200)
}));

const prompt = `You are my personal news assistant. Below are my unread RSS articles from the last 24 hours.

Tasks:
1. Group articles by topic (e.g. Football, World News, Tech, etc.)
2. Select the most important/interesting — max 10 total across all groups
3. For each, write ONE concise sentence summarizing the key point
4. Skip duplicates and clickbait

Format as a Telegram message:
⚽ *Football*
• Title — Summary. (Feed Name)

🌍 *World News*
• Title — Summary. (Feed Name)

Max 350 words. Use relevant emoji for each category heading.

Articles:
${JSON.stringify(articleList)}`;

return [{ json: { hasEntries: true, count: entries.length, prompt } }];

const gemRes = $input.first().json;
const prev = $('Prepare for AI').first().json;

let digest = '';
try {
  digest = gemRes.candidates[0].content.parts[0].text.trim();
} catch(e) {
  digest = 'AI summarization unavailable — check Gemini API key.';
}

const date = new Date().toLocaleDateString('en-IN', {
  weekday: 'short', day: 'numeric', month: 'short',
  timeZone: 'Asia/Kolkata'
});

const msg = `📰 *Morning Digest — ${date}*
_(${prev.count} articles scanned)_

${digest}`;

return [{ json: { message: msg } }];
